// Map categories (generated by tools/mapatlas/gen_categories.py from research/x3/atlas/categories_rules.json;
// see research/x3/atlas/CATEGORIES.md). Index = category number - 1.
#pragma once
#include "x1_atlas.h"
#include <cmath>

namespace x1_categories {

inline constexpr int kNumCats = 7;

inline int classify(const x1_atlas::Features& f) {
    if (std::log(static_cast<float>(f.w) * static_cast<float>(f.h)) <= 7.8823f) {
        if (std::log(1.0f + f.mean_dist) <= 3.1377f) {
            if (f.harmless <= 0.623f) {
                return 0; // C1
            }
                return 1; // C2
        }
            if (f.harmless <= 0.1725f) {
                return 2; // C3
            }
                return 3; // C4
    }
        if (f.harmless <= 0.459f) {
            if (f.near30 <= 0.578f) {
                return 4; // C5
            }
                return 5; // C6
        }
            return 6; // C7
}

} // namespace x1_categories
